<?php require_once dirname(__DIR__) . '/app/config.php';require_login();$st=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$st->execute([user()['id']]);$orders=$st->fetchAll();header_html('Lịch sử đơn hàng');?><h1 class="fw-bold mb-4">Lịch sử mua hàng</h1><?php if(!$orders):?><div class="empty-state">Bạn chưa có đơn hàng nào.</div><?php else:?><div class="row g-3"><?php foreach($orders as $o):?><div class="col-12"><div class="card p-3 border-0 shadow-sm"><div class="d-flex justify-content-between flex-wrap"><strong>Đơn hàng #<?=$o['id']?></strong><span class="badge bg-<?=$o['status']==='completed'?'success':($o['status']==='cancelled'?'danger':'primary')?>"><?=e($o['status'])?></span></div><div class="text-muted small mt-2"><?=e($o['created_at'])?> · <?=e($o['customer_name'])?> · <?=e($o['phone'])?></div><p class="mb-1 mt-2"><?=e($o['address'])?></p><strong class="price"><?=money($o['total'])?></strong><a class="small mt-2" href="order_detail.php?id=<?=$o['id']?>">Xem chi tiết</a></div></div><?php endforeach;?></div><?php endif;?><?php footer_html();?>
